"use client";

import { useEffect, useRef, useState } from "react";
import { Box, ChevronLeft, ChevronRight, Minus, Plus, Square } from "lucide-react";
import type { Plan3D, PlanWalls } from "@/lib/plan3d";

/** Maps "/images/plans/<id>.webp" → "/plans3d/<id>" assets generated by scripts/plans3d.py */
const assetBase = (planSrc: string) => planSrc.replace("/images/plans/", "/plans3d/").replace(/\.webp$/, "");

export default function FloorPlan3D({ planSrc, label }: { planSrc: string; label: string }) {
  const host = useRef<HTMLDivElement>(null);
  const view = useRef<Plan3D | null>(null);
  const [state, setState] = useState<"loading" | "ready" | "error">("loading");

  useEffect(() => {
    let alive = true;
    let v: Plan3D | null = null;
    const base = assetBase(planSrc);
    (async () => {
      try {
        const res = await fetch(`${base}.json`);
        if (!res.ok) throw new Error("walls");
        const walls = (await res.json()) as PlanWalls;
        const { mountPlan3D } = await import("@/lib/plan3d");
        if (!alive || !host.current) return;
        v = await mountPlan3D(host.current, `${base}.webp`, walls);
        if (!alive) return v.destroy();
        view.current = v;
        setState("ready");
      } catch {
        if (alive) setState("error");
      }
    })();
    return () => {
      alive = false;
      v?.destroy();
      view.current = null;
    };
  }, [planSrc]);

  const ctl = "inline-flex size-10 items-center justify-center bg-ivory/90 text-charcoal transition-colors hover:bg-gold disabled:opacity-40";
  const ready = state === "ready";

  return (
    <div className="relative aspect-[4/3] w-full overflow-hidden bg-[#e9e5db] sm:aspect-[2516/1790]" data-testid="plan3d" data-state={state}>
      <div ref={host} className="absolute inset-0 cursor-grab active:cursor-grabbing" role="img" aria-label={`3D view of the ${label} floor plan. Drag to rotate, pinch or scroll to zoom.`} />
      {state === "loading" && <p className="absolute inset-0 flex items-center justify-center text-sm text-charcoal/70" role="status">Building 3D view…</p>}
      {state === "error" && <p className="absolute inset-0 flex items-center justify-center p-6 text-center text-sm text-charcoal/80" role="alert">The 3D view isn&apos;t available on this device. Please use the 2D plan.</p>}
      <span className="pointer-events-none absolute left-3 top-3 whitespace-nowrap bg-ink/70 px-2 py-1 text-xs uppercase tracking-[0.1em] text-ivory sm:tracking-[0.16em]">
        3D from official plan · not to scale
      </span>
      <div className="absolute bottom-3 right-3 flex flex-wrap justify-end gap-1.5">
        <button type="button" className={ctl} disabled={!ready} aria-label="Rotate left" onClick={() => view.current?.rotate(-30)}><ChevronLeft className="size-4" aria-hidden /></button>
        <button type="button" className={ctl} disabled={!ready} aria-label="Rotate right" onClick={() => view.current?.rotate(30)}><ChevronRight className="size-4" aria-hidden /></button>
        <button type="button" className={ctl} disabled={!ready} aria-label="Zoom in" onClick={() => view.current?.zoom(0.8)}><Plus className="size-4" aria-hidden /></button>
        <button type="button" className={ctl} disabled={!ready} aria-label="Zoom out" onClick={() => view.current?.zoom(1.25)}><Minus className="size-4" aria-hidden /></button>
        <button type="button" className={ctl} disabled={!ready} aria-label="Top view" onClick={() => view.current?.topView()} data-testid="plan3d-top"><Square className="size-4" aria-hidden /></button>
        <button type="button" className={ctl} disabled={!ready} aria-label="3D view" onClick={() => view.current?.isoView()}><Box className="size-4" aria-hidden /></button>
      </div>
    </div>
  );
}
